const body = $json;
const events = Array.isArray(body?.events) ? body.events : [];

function mapEvent(e){
  const comp = e?.competitions?.[0];
  const competitors = comp?.competitors || [];
  const home = competitors.find(c => c?.homeAway === 'home');
  const away = competitors.find(c => c?.homeAway === 'away');

  return {
    eventId: String(e?.id || ''),
    name: e?.name || e?.shortName || 'Game',
    shortName: e?.shortName || e?.name || 'Game',
    startTime: e?.date || null,
    status: e?.status?.type?.state || 'unknown',
    homeTeam: home?.team?.displayName || home?.team?.name || 'Home',
    awayTeam: away?.team?.displayName || away?.team?.name || 'Away'
  };
}

const games = events.map(mapEvent).filter(g => g.eventId);

// Sort: in-progress first, then upcoming, then finished; then by time
const rank = (s) => (s === 'in' ? 0 : s === 'pre' ? 1 : s === 'post' ? 2 : 3);
games.sort((a,b)=> rank(a.status) - rank(b.status) || (Date.parse(a.startTime||'') - Date.parse(b.startTime||'')));

return [{ games }];

function pickFallback(events) {
  if (!Array.isArray(events) || events.length === 0) return null;

  // Prefer Super Bowl wording, then in-progress, then pre
  const score = (e) => {
    const status = e?.status?.type?.state || '';
    const name = (e?.name || '').toLowerCase();
    const shortName = (e?.shortName || '').toLowerCase();

    const isSB = name.includes('super bowl') || shortName.includes('super bowl');
    let s = isSB ? 1000 : 0;

    if (status === 'in') s += 500;
    if (status === 'pre') s += 200;
    if (status === 'post') s += 50;

    const start = Date.parse(e?.date || '') || 0;
    s += Math.floor(start / 1e9);

    return s;
  };

  return events.slice().sort((a,b)=> score(b) - score(a))[0];
}

const q = $json.query || {};
const wantedId = (q.eventId || '').toString().trim();

const body = $items('Fetch ESPN Scoreboard (for live)')[0].json;
const events = Array.isArray(body?.events) ? body.events : [];

let game = null;
if (wantedId) {
  game = events.find(e => String(e?.id || '') === wantedId) || null;
}
if (!game) {
  game = pickFallback(events);
}
if (!game) return [{ error: 'NO_GAMES', message: 'No games found.' }];

const comp = game?.competitions?.[0];
const competitors = comp?.competitors || [];
const home = competitors.find(c => c?.homeAway === 'home');
const away = competitors.find(c => c?.homeAway === 'away');

const homeName = home?.team?.displayName || home?.team?.name || 'Home';
const awayName = away?.team?.displayName || away?.team?.name || 'Away';

const homeScore = parseInt(home?.score ?? '0', 10);
const awayScore = parseInt(away?.score ?? '0', 10);

const statusState = game?.status?.type?.state || 'unknown';
const quarter = game?.status?.period ?? '-';
const clock = game?.status?.displayClock ?? '--:--';

return [{
  eventId: String(game?.id || ''),
  leftTeam: homeName,
  topTeam: awayName,
  leftScore: Number.isFinite(homeScore) ? homeScore : 0,
  topScore: Number.isFinite(awayScore) ? awayScore : 0,
  quarter,
  clock,
  status: statusState,
  possession: '--'
}];
